import * as React from "react"
import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

/*
 * Graphite Button — the only "accent" surface in the system: a raised pill.
 *   - Gentle top->bottom gradient fill (light from above)
 *   - Hairline white border at ~7% (via border-border)
 *   - Inset top-edge highlight + soft outer drop shadow (--shadow-pill)
 *   - Active label sinks with a text-shadow; the pill nudges down on press
 *   - Secondary/outline/ghost stay calm tiles or flat surfaces, never glowy
 */

const buttonVariants = cva(
  [
    "inline-flex items-center justify-center gap-2 whitespace-nowrap",
    "text-sm font-medium leading-none tracking-[-0.01em]",
    "rounded-full cursor-pointer select-none",
    "transition-[background,box-shadow,transform,color] duration-fast",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
    "disabled:pointer-events-none disabled:opacity-50",
    "active:translate-y-px",
  ].join(" "),
  {
    variants: {
      variant: {
        default:
          "bg-[image:var(--pill-gradient)] text-primary-foreground " +
          "[text-shadow:var(--text-shadow-pressed)] " +
          "[box-shadow:var(--shadow-pill)] " +
          "hover:bg-[image:var(--pill-gradient-hover)] hover:[box-shadow:var(--shadow-pill-hover)] " +
          "active:[box-shadow:var(--shadow-sm)]",
        primary:
          "bg-[image:var(--pill-gradient)] text-primary-foreground " +
          "[text-shadow:var(--text-shadow-pressed)] " +
          "[box-shadow:var(--shadow-pill)] " +
          "hover:bg-[image:var(--pill-gradient-hover)] hover:[box-shadow:var(--shadow-pill-hover)] " +
          "active:[box-shadow:var(--shadow-sm)]",
        secondary:
          "bg-secondary text-secondary-foreground " +
          "[box-shadow:var(--shadow-tile)] " +
          "hover:bg-accent hover:text-foreground hover:[box-shadow:var(--shadow-md)] " +
          "active:[box-shadow:var(--shadow-xs)]",
        outline:
          "bg-transparent text-foreground border border-border " +
          "[box-shadow:var(--shadow-tile)] " +
          "hover:bg-accent hover:border-foreground/15",
        ghost:
          "bg-transparent text-muted-foreground " +
          "hover:bg-accent hover:text-foreground",
        destructive:
          "bg-destructive text-destructive-foreground " +
          "[box-shadow:var(--shadow-pill)] " +
          "hover:brightness-110 hover:[box-shadow:var(--shadow-pill-hover)]",
        link: "text-foreground underline-offset-4 hover:underline",
      },
      size: {
        sm: "h-8 px-3 text-xs",
        default: "h-9 px-4",
        lg: "h-11 px-6",
        icon: "h-9 w-9",
        "icon-sm": "h-8 w-8",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

export interface ButtonProps
  extends Omit<ButtonPrimitive.Props, "className">,
    VariantProps<typeof buttonVariants> {
  className?: string
  asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    // Callers written against the Radix API pass the element to become as a
    // child: <Button asChild><Link>…</Link></Button>. Base UI has no asChild,
    // it composes through `render`. Without this the prop reaches the DOM and
    // the anchor nests inside the button instead of replacing it, which stacks
    // the icon above the label and puts a link inside a button.
    if (asChild && React.isValidElement(props.children)) {
      const { children, ...rest } = props
      return (
        <ButtonPrimitive
          ref={ref}
          className={cn(buttonVariants({ variant, size, className }))}
          {...rest}
          // After the spread, so an explicit asChild child wins over a stray
          // render prop rather than being silently replaced by it.
          // SAFETY: this branch runs only when `asChild` is set, and the caller then
          // owns passing a single element for the slot to clone.
          render={children as React.ReactElement}
        />
      )
    }

    return (
    <ButtonPrimitive
      className={cn(buttonVariants({ variant, size, className }))}
      ref={ref}
      {...props}
    />
    )
  }
)
Button.displayName = "Button"

export { Button, buttonVariants }
